      "fit_reason": "SRI options become part of HTML attributes, requiring proper character neutralization"
    },
    {
      "cwe_id": "CWE-116",
      "cwe_name": "Improper Encoding or Escaping of Output",
      "fit_reason": "Character set validation ensures proper encoding of options in HTML integrity attributes"
    },
    {
      "cwe_id": "CWE-730",
